# Generate the Slint .po view and the Rust runtime catalog from lang/catalog.json.
# The JSON file is the single authoring source. -Check verifies generated files.
param(
    [string]$Source = "lang/catalog.json",
    [string]$Po = "crates/slint-ui/lang/en_US/LC_MESSAGES/flint-slint.po",
    [string]$Rust = "crates/slint-ui/src/i18n_catalog.rs",
    [switch]$Check
)

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot
Set-Location $root
$catalog = Get-Content $Source -Raw -Encoding UTF8 | ConvertFrom-Json
$escapePo = {
    param($s)
    $s.Replace('\', '\\').Replace('"', '\"').Replace("`r`n", '\n').Replace("`n", '\n')
}
$escapeRust = {
    param($s)
    $s.Replace('\', '\\').Replace('"', '\"').Replace("`r`n", '\n').Replace("`n", '\n').Replace("`t", '\t')
}
$sb = [Text.StringBuilder]::new()
[void]$sb.AppendLine('msgid ""')
[void]$sb.AppendLine('msgstr ""')
[void]$sb.AppendLine('"Project-Id-Version: Flint 0.1.69\n"')
[void]$sb.AppendLine('"Content-Type: text/plain; charset=UTF-8\n"')
[void]$sb.AppendLine('"Language: en_US\n"')
[void]$sb.AppendLine('"MIME-Version: 1.0\n"')
foreach ($entry in $catalog.static) {
    [void]$sb.AppendLine()
    if ($entry.ctx) { [void]$sb.AppendLine("msgctxt `"$(& $escapePo $entry.ctx)`"") }
    [void]$sb.AppendLine("msgid `"$(& $escapePo $entry.key)`"")
    [void]$sb.AppendLine("msgstr `"$(& $escapePo $entry.en)`"")
}
$poText = $sb.ToString().Replace("`r`n", "`n")
$rb = [Text.StringBuilder]::new()
[void]$rb.AppendLine('// Generated by tools/i18n-gen.ps1 from lang/catalog.json. Do not edit.')
[void]$rb.AppendLine('const CATALOG: &[(&str, &str)] = &[')
foreach ($entry in $catalog.dynamic) {
    [void]$rb.AppendLine("    (`"$(& $escapeRust $entry.key)`", `"$(& $escapeRust $entry.en)`"),")
}
[void]$rb.AppendLine('];')
$rustText = $rb.ToString().Replace("`r`n", "`n")
if ($Check) {
    if ((Get-Content $Po -Raw -Encoding UTF8) -ne $poText) { throw "generated .po is stale; run tools/i18n-gen.ps1" }
    if ((Get-Content $Rust -Raw -Encoding UTF8) -ne $rustText) { throw "generated Rust catalog is stale; run tools/i18n-gen.ps1" }
    Write-Host "i18n source is current"
    exit 0
}
[IO.File]::WriteAllText((Join-Path $root $Po), $poText, (New-Object Text.UTF8Encoding($false)))
[IO.File]::WriteAllText((Join-Path $root $Rust), $rustText, (New-Object Text.UTF8Encoding($false)))
Write-Host "generated: $Po, $Rust"
